import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { createRequest, submitRequest, uploadAttachment } from '../services/requestService';
import { getWorkflows } from '../services/workflowService';
import { toast } from 'react-toastify';

const RequestForm = () => {
  const navigate = useNavigate();
  const [workflows, setWorkflows] = useState([]);
  const [selectedWorkflow, setSelectedWorkflow] = useState('');
  const [formData, setFormData] = useState({});
  const [files, setFiles] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    loadWorkflows();
  }, []);

  const loadWorkflows = async () => {
    const data = await getWorkflows();
    setWorkflows(data);
    if (data.length) setSelectedWorkflow(data[0].name);
  };

  const handleFieldChange = (field, value) => {
    setFormData({ ...formData, [field]: value });
  };

  const handleFileChange = (e) => {
    setFiles([...files, ...Array.from(e.target.files)]);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      // Créer la demande
      const request = await createRequest({
        workflowType: selectedWorkflow,
        data: formData,
      });
      // Uploader les fichiers
      for (const file of files) {
        await uploadAttachment(request.id, file);
      }
      // Soumettre la demande
      await submitRequest(request.id);
      toast.success('Demande créée et soumise avec succès');
      navigate('/requests');
    } catch (error) {
      toast.error('Erreur lors de la création');
    } finally {
      setLoading(false);
    }
  };

  const renderFields = () => {
    // Simplifié: à adapter selon le workflow sélectionné
    return (
      <>
        <div className="form-group">
          <label>Société</label>
          <select onChange={(e) => handleFieldChange('societe', e.target.value)}>
            <option value="SK">SK</option>
            <option value="SF">SF</option>
          </select>
        </div>
        <div className="form-group">
          <label>Montant</label>
          <input type="number" onChange={(e) => handleFieldChange('montant', e.target.value)} />
        </div>
        <div className="form-group">
          <label>Motif</label>
          <textarea onChange={(e) => handleFieldChange('motif', e.target.value)} />
        </div>
        <div className="form-group">
          <label>Choix caisse</label>
          <select onChange={(e) => handleFieldChange('choixCaisse', e.target.value)}>
            <option value="Usine">Usine</option>
            <option value="Siège">Siège</option>
          </select>
        </div>
      </>
    );
  };

  return (
    <div className="max-w-2xl mx-auto">
      <h1 className="text-2xl font-bold mb-6">Nouvelle demande</h1>
      <form onSubmit={handleSubmit} className="card">
        <div className="form-group">
          <label>Type de workflow</label>
          <select value={selectedWorkflow} onChange={(e) => setSelectedWorkflow(e.target.value)}>
            {workflows.map(w => <option key={w.name} value={w.name}>{w.name}</option>)}
          </select>
        </div>
        
        {renderFields()}
        
        <div className="form-group">
          <label>Pièces jointes</label>
          <input type="file" multiple onChange={handleFileChange} />
        </div>
        
        <button type="submit" className="btn btn-primary" disabled={loading}>
          {loading ? 'Envoi...' : 'Créer et soumettre'}
        </button>
      </form>
    </div>
  );
};

export default RequestForm;
